mapper.sql:
SELECT coalesce(nullif(t.trace_id, ''), '#span#' || t.id) AS link_id, 'span' AS node_kind, t.start_time AS start_time, t.start_time + coalesce(t.duration, 0) * interval '1 millisecond' AS end_time, t.duration AS duration, NULL::bigint AS total_tokens, NULL::varchar AS app_id, NULL::varchar AS app_name, NULL::varchar AS session_id, NULL::varchar AS user_id, NULL::varchar AS model_name, t.status AS node_status, t.message AS error_message, ((t.span_id = t.trace_id) OR t.trace_id IS NULL OR t.trace_id = '') AS is_entry, nullif(coalesce(nullif(t.module, ''), '') || coalesce('/' || nullif(t.action, ''), ''), '') AS entry_label FROM trace_record t WHERE t.deleted = 0 AND t.id = #{q.orphanId} AND t.trace_id = #{q.linkId} AND t.start_time >= #{q.startTime} AND t.start_time <= #{q.endTime}
UNION ALL
SELECT coalesce(nullif(l.trace_id, ''), '#llm#' || l.id) AS link_id, 'llm' AS node_kind, l.start_time AS start_time, l.start_time + coalesce(l.duration, 0) * interval '1 millisecond' AS end_time, l.duration AS duration, l.total_tokens AS total_tokens, l.app_id AS app_id, l.app_name AS app_name, l.session_id AS session_id, l.user_id AS user_id, l.model_name AS model_name, l.status AS node_status, l.error_message AS error_message, (l.trace_id IS NULL OR l.trace_id = '') AS is_entry, l.model_name AS entry_label FROM llm_trace l WHERE l.deleted = 0 AND l.id = #{q.orphanId} AND l.trace_id = #{q.linkId} AND l.start_time >= #{q.startTime} AND l.start_time <= #{q.endTime}
UNION ALL
SELECT coalesce(nullif(r.trace_id, ''), '#run#' || r.id) AS link_id, 'run' AS node_kind, r.start_time AS start_time, coalesce(r.end_time, r.start_time + coalesce(r.duration, 0) * interval '1 millisecond') AS end_time, r.duration AS duration, r.total_tokens AS total_tokens, r.app_id AS app_id, r.app_name AS app_name, r.session_id AS session_id, r.user_id AS user_id, r.model_name AS model_name, r.status AS node_status, r.error_message AS error_message, (r.parent_run_id IS NULL) AS is_entry, r.harness_type AS entry_label FROM agent_run r WHERE r.deleted = 0 AND r.id = #{q.orphanId} AND r.trace_id = #{q.linkId} AND r.start_time >= #{q.startTime} AND r.start_time <= #{q.endTime}

mapper.select:
AND node.link_id LIKE concat('%', #{q.traceId}, '%')
GROUP BY node.link_id
ORDER BY min(node.start_time) DESC LIMIT #{limit} OFFSET #{offset}
